import { TFile } from "obsidian";
// Generated by scripts/build-elm.mjs before TypeScript is checked or bundled.
// @ts-expect-error The generated module does not exist in a clean checkout.
import { Elm } from "../../.generated/elm-runtime.js";
import type { ChecklistService } from "../checklists/checklist-service";
import { checklistOverview } from "../domain/checklist";
import { moveProject, setProjectStatus } from "../ui/project-moves";
import type { GtdServices } from "../ui/services";
import { localDate } from "../utils/date";
import { assertNever, subscribeElmCommands, type ElmOutgoingPort } from "./elm-host";
import {
  elmSnapshot,
  parseSomedayReviewCommand,
  type ElmSomedayReviewCommand,
  type ElmReviewChecklistDto,
  type ElmSomedayReviewEvent,
  type ElmSnapshotDto,
} from "./protocol";

interface ElmApp {
  ports: {
    somedayToHost: ElmOutgoingPort;
    somedayFromHost: { send(value: ElmSomedayReviewEvent): void };
  };
}

/**
 * Hosts the Someday/Maybe Review, where each parked idea gets a decision. It is the Weekly
 * Review's last step, so it also lists the checklists to look over.
 */
export class ElmSomedayReviewHost {
  private readonly app: ElmApp;
  private readonly unsubscribe: () => void;
  private readonly unsubscribeChecklists: () => void;
  private readonly unsubscribePort: () => void;
  private closed = false;

  constructor(node: HTMLElement, private readonly services: GtdServices, private readonly checklists: ChecklistService) {
    const module = Elm.SomedayReview;
    if (!module) throw new Error("The Elm SomedayReview module was not compiled.");
    this.app = module.init({ node, flags: { snapshot: this.snapshot(), checklists: this.checklistOverview() } }) as ElmApp;
    this.unsubscribePort = subscribeElmCommands({
      port: this.app.ports.somedayToHost,
      parse: parseSomedayReviewCommand,
      execute: (command) => this.execute(command),
      reply: (event) => this.send(event),
      surface: "Someday/Maybe Review",
      failureMessage: "The Someday/Maybe Review operation failed.",
    });
    this.unsubscribe = services.repository.index.subscribe(() => this.refresh(), "Someday/Maybe Review");
    this.unsubscribeChecklists = checklists.subscribe(() => this.send({ type: "checklists", checklists: this.checklistOverview() }));
  }

  refresh(): void {
    this.send({ type: "snapshot", snapshot: this.snapshot() });
    this.send({ type: "checklists", checklists: this.checklistOverview() });
  }

  destroy(): void {
    this.closed = true;
    this.unsubscribePort();
    this.unsubscribe();
    this.unsubscribeChecklists();
  }

  private checklistOverview(): ElmReviewChecklistDto[] {
    const settings = this.services.getSettings().checklists;
    return checklistOverview(this.checklists.getStore(), this.checklists.checklists()).map((checklist) => ({
      ...checklist,
      role: checklist.path === settings.daily ? "daily" : checklist.path === settings.focusReset ? "focus-reset" : null,
    }));
  }

  private snapshot(): ElmSnapshotDto {
    return elmSnapshot(this.services.repository.index.getSnapshot(), this.services.getSettings(), localDate());
  }

  private send(event: ElmSomedayReviewEvent): void {
    if (!this.closed) this.app.ports.somedayFromHost.send(event);
  }

  private async execute(command: ElmSomedayReviewCommand): Promise<unknown> {
    switch (command.type) {
      case "set-project-status":
        return setProjectStatus(this.services, command.projectId, command.status);
      case "move-subproject":
        return moveProject(this.services, command.projectId, command.status, command.beforeId);
      case "review-someday-project":
        // Keeping an idea is a decision too; the date lets it wake itself up later.
        return this.services.repository.updateProject(command.projectId, { activateAt: command.activateAt, reviewed: localDate() });
      case "show-project":
        this.services.showProjectDetail(command.projectId);
        return;
      case "open-file": {
        const file = this.services.app.vault.getAbstractFileByPath(command.path);
        if (!(file instanceof TFile)) throw new Error(`File '${command.path}' no longer exists.`);
        return this.services.openFile(file);
      }
    }
    return assertNever(command);
  }
}
